export class SortingWixError extends Error {
  /** @hidden */
  httpCode: number;
  /** @hidden */
  statusCode: string;
  /** @hidden */
  applicationCode: string;
  /** @hidden */
  name: string;
  /** @hidden */
  errorType: string;
  /** @hidden */
  spiErrorData: object;

  constructor() {
    super('SortingError');

    this.httpCode = 400;
    this.statusCode = 'INVALID_ARGUMENT';
    this.applicationCode = 'SORTING_ERROR';
    this.name = 'SortingError';
    this.errorType = 'SPI';
    this.spiErrorData = {
      name: 'SortingError',
      applicationCode: 'SORTING_ERROR',
    };
  }

  /** @hidden */
  static readonly __type = 'wix_spi_error';
}
