export interface SortStaffMembersRequest {
  /**
   * ID of the service's [booking policy](https://dev.wix.com/docs/api-reference/business-solutions/bookings/policies/booking-policies/introduction).
   * @format GUID
   */
  policyId?: string | null;
  /**
   * Booking slot context including time, service, and location details.
   * You can use this information to make informed sorting decisions based on factors like staff proximity to location, expertise with the specific service, or availability patterns.
   */
  slot?: Slot;
  /**
   * Array of resource IDs for staff members who are available for this time slot.
   * The field uses "resource" terminology for future extensibility, but currently all resources are staff members.
   * Your algorithm must return these same IDs in your preferred assignment order.
   * Don't add, remove, or duplicate resources.
   * @format GUID
   * @minSize 1
   * @maxSize 50
   */
  availableResourceIds?: string[];
  /** Custom field data for the policy. [Extended fields](https://dev.wix.com/docs/rest/articles/getting-started/extended-fields) must be configured in the app dashboard before they can be accessed with API calls. */
  extendedFields?: ExtendedFields;
}

export interface Slot {
  /**
   * Local start time of the booking slot in `YYYY-MM-DDThh:mm:ss` [ISO-8601 format](https://en.wikipedia.org/wiki/ISO_8601).
   * For example, `2026-01-30T13:30:00`.
   * Wix always provides this value when calling your service plugin.
   * @maxLength 30
   */
  startDate?: string | null;
  /**
   * Local end time of the booking slot in `YYYY-MM-DDThh:mm:ss` [ISO-8601 format](https://en.wikipedia.org/wiki/ISO_8601).
   * For example, `2026-01-30T14:00:00`.
   * Wix always provides this value when calling your service plugin.
   * @maxLength 30
   */
  endDate?: string | null;
  /**
   * ID of the [service](https://dev.wix.com/docs/api-reference/business-solutions/bookings/services/services-v2/introduction) being booked.
   * Wix always provides this value when calling your service plugin.
   * @format GUID
   */
  serviceId?: string | null;
  /**
   * ID of the [location](https://dev.wix.com/docs/api-reference/business-management/locations/introduction) where the business provides the service.
   * Consider this for proximity-based sorting or location-specific staff assignments.
   * Wix always provides this value when calling your service plugin.
   * @format GUID
   */
  locationId?: string | null;
  /**
   * Time zone for the slot. For example, `America/New_York` or `UTC`.
   * Wix always provides this value when calling your service plugin.
   * @minLength 1
   * @maxLength 150
   */
  timeZone?: string | null;
}

export interface ExtendedFields {
  /**
   * Extended field data. Each key corresponds to the namespace of the app that created the extended fields.
   * The value of each key is structured according to the schema defined when the extended fields were configured.
   *
   * You can only access fields for which you have the appropriate permissions.
   *
   * Learn more about [extended fields](https://dev.wix.com/docs/rest/articles/getting-started/extended-fields).
   */
  namespaces?: Record<string, Record<string, any>>;
}

export interface SortStaffMembersResponse {
  /**
   * Array of staff members sorted according to your custom sorting algorithm, in order of assignment priority.
   * Wix assigns the first staff member to the booking.
   * Subsequent staff members serve as fallbacks if the primary choice becomes unavailable during the booking process.
   * @maxSize 50
   */
  staff?: Staff[];
}

export interface Staff {
  /**
   * Resource ID. This must match one of the IDs specified in the SortStaffMembersRequest.available_resource_ids array.
   * Currently, this service plugin only supports staff members as resources.
   * @format GUID
   */
  resourceId?: string;
}

export interface StaffSortingProviderConfig {
  /**
   * Base URI where you deploy your service plugin implementation. Wix appends the method path to this base URI when calling your SortStaffMembers method.
   * For example, if your base URI is `https://example-staff-sorter.com/`, Wix calls `https://example-staff-sorter.com/v1/sort-staff-members`.
   */
  deploymentUri?: SpiBaseUri;
  /**
   * Name for your custom sorting method that's displayed to Wix users in the dashboard when selecting a staff assignment method.
   * Use clear, benefit-focused language. For example, `Workload Balancer`, `Customer Preference Matching`, or `AI-Powered Optimizer`.
   * Avoid technical jargon.
   * @maxLength 100
   */
  methodName?: string;
  /**
   * Clear explanation of how your sorting method works and which factors it considers.
   * Explain what business problems it solves and when to use this method.
   * For example, `Assigns staff based on current workload, ensuring fair distribution of bookings across your team. Best for businesses prioritizing balanced work schedules.`
   * @maxLength 100
   */
  methodDescription?: string;
  /**
   * ID of the [staff assignment dashboard slot](https://dev.wix.com/docs/build-apps/develop-your-app/extensions/dashboard-extensions/dashboard-plugins/supported-wix-app-dashboard-pages/wix-bookings/wix-bookings-booking-policies-page#slot-staff-assignment) that provides a configuration interface for your sorting method. The slot displays your configuration interface in the [Booking Policies page](https://dev.wix.com/docs/build-apps/develop-your-app/extensions/dashboard-extensions/dashboard-plugins/supported-wix-app-dashboard-pages/wix-bookings/wix-bookings-booking-policies-page) when Wix users select your sorting method, allowing them to learn about your algorithm and customize its parameters. Learn more about [dashboard plugins](https://dev.wix.com/docs/build-apps/develop-your-app/extensions/dashboard-extensions/dashboard-plugins/about-dashboard-plugin-extensions).
   * @format GUID
   */
  dashboardPluginId?: string | null;
}

/** Base URI configuration for a service plugin. Wix uses these URIs to call your service plugin methods. */
export interface SpiBaseUri {
  /**
   * Base URI for your service plugin. Wix appends each method's path to this URI.
   *
   * For example, to receive requests at `https://my-app.com/v1/my-method`, set this field to `https://my-app.com/`.
   * @minLength 6
   * @maxLength 2048
   */
  baseUri?: string;
  /** Alternative URIs for specific methods. Use these to override the default URI for individual methods. */
  alternativeUris?: AlternativeUri[];
}

/** Custom URI for the specified service plugin method. */
export interface AlternativeUri {
  /**
   * Name of the method to call at the absolute URI, in PascalCase. For example, to call [Get Shipping Rates](https://dev.wix.com/docs/api-reference/business-solutions/e-commerce/extensions/shipping-rates/shipping-rates-integration-service-plugin/get-shipping-rates) on an alternative URI, specify `GetShippingRates`.
   * @minLength 3
   * @maxLength 128
   */
  methodName?: string;
  /**
   * Absolute URI that Wix calls for this method. Wix doesn't append any path to this URI.
   *
   * The URI must begin with `https://`, such as `https://my-app.com/v1/my-custom-method`.
   * @minLength 6
   * @maxLength 2048
   */
  absoluteUri?: string;
}

/**
 * this message is not directly used by any service,
 * it exists to describe the expected parameters that SHOULD be provided to invoked Velo methods as part of open-platform.
 * e.g. SPIs, event-handlers, etc..
 * NOTE: this context object MUST be provided as the last argument in each Velo method signature.
 *
 * Example:
 * ```typescript
 * export function wixStores_onOrderCanceled({ event, metadata }: OrderCanceledEvent) {
 * ...
 * }
 * ```
 */
export interface Context {
  /** A unique identifier of the request. You may print this ID to your logs to help with future debugging and easier correlation with Wix's logs. */
  requestId?: string | null;
  /**
   * [ISO 4217](https://en.wikipedia.org/wiki/ISO_4217) 3-letter currency code.
   * @format CURRENCY
   */
  currency?: string | null;
  /** An object that describes the identity that triggered this request. */
  identity?: IdentificationData;
  /** A string representing a language and region in the format of `"xx-XX"`. First 2 letters represent the language code according to ISO 639-1. This is followed by a dash "-", and then a by 2 capital letters representing the region according to ISO 3166-2. For example, `"en-US"`. */
  languages?: string[];
  /**
   * The service provider app's instance ID.
   * @format GUID
   */
  instanceId?: string | null;
  /**
   * Extension ID in Dev Center.
   * @internal
   * @maxLength 256
   */
  appExtensionId?: string | null;
  /**
   * Extension type in Dev Center.
   * @internal
   * @maxLength 256
   */
  appExtensionType?: string | null;
  /**
   * Invoked function.
   * @internal
   * @maxLength 256
   */
  functionName?: string | null;
}

export enum IdentityType {
  UNKNOWN = 'UNKNOWN',
  ANONYMOUS_VISITOR = 'ANONYMOUS_VISITOR',
  MEMBER = 'MEMBER',
  WIX_USER = 'WIX_USER',
  APP = 'APP',
}

export interface IdentificationData extends IdentificationDataIdOneOf {
  /**
   * ID of a site visitor that has not logged in to the site.
   * @format GUID
   */
  anonymousVisitorId?: string;
  /**
   * ID of a site visitor that has logged in to the site.
   * @format GUID
   */
  memberId?: string;
  /**
   * ID of a Wix user (site owner, contributor, etc.).
   * @format GUID
   */
  wixUserId?: string;
  /**
   * ID of an app.
   * @format GUID
   */
  appId?: string;
  /** @readonly */
  identityType?: IdentityType;
}

/** @oneof */
export interface IdentificationDataIdOneOf {
  /**
   * ID of a site visitor that has not logged in to the site.
   * @format GUID
   */
  anonymousVisitorId?: string;
  /**
   * ID of a site visitor that has logged in to the site.
   * @format GUID
   */
  memberId?: string;
  /**
   * ID of a Wix user (site owner, contributor, etc.).
   * @format GUID
   */
  wixUserId?: string;
  /**
   * ID of an app.
   * @format GUID
   */
  appId?: string;
}
